  assert.throws(() => verifyReceipt(bundle, {...options, compatible: vouch(true), headSha: '0'.repeat(40)}), /changed/);
  assert.throws(() => verifyReceipt(bundle, {...options, compatible: vouch(true), author: 'unregistered-contributor'}), /PR author/);
