  let calls = 0;
  f.github.graphql = async () => {
    calls++;
    f.state.pr.auto_merge = {};
    throw graphqlBlip();
  };
  await f.run();
  assert.equal(calls, 1);
  assert.deepEqual(f.waits, [2000]);
